// 対象日(Asia/Tokyo の今日) と Kintone 取得URLを組み立てる
// 日報アプリは日付がサブテーブル内にあるため、kintoneのクエリでは絞り込めない。
// 全件取得して、次のノードでコード側で展開・絞り込みを行う。
const tz = $env.REPORT_TIMEZONE || 'Asia/Tokyo';
const dateISO = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const base = ($env.KINTONE_BASE_URL || '').replace(/\/$/, '');
const app = $env.KINTONE_DAILY_REPORT_APP_ID;
const query = 'order by $id desc limit 500';
const url = `${base}/k/v1/records.json?app=${app}&query=${encodeURIComponent(query)}`;
return [{ json: { dateISO, url } }];

// 抽出済みの日報からClaudeへの入力を組み立てる
const dateISO = $json.dateISO;
const reports = ($json.reports || []).map(r => ({
  report_date: r.date, reporter: r.reporter || '（氏名不明）', team: r.team || null, body: r.text
}));
const input = { dateISO, company: '株式会社リベティ (Libetee)', reports, previousIssues: [], report_count: reports.length,
  note: '各日報は自由記述の本文です。項目が分かれていないため、本文から成果・問題・依頼などを読み取ってください。' };
const system = $env.CLAUDE_SYSTEM_PROMPT || 'あなたはLibeteeの業務分析アシスタント。日報を分析し指定JSONのみを出力する。情報不足は"情報不足"と書く。bodyは自由記述の本文なので読み取って判断する。スキーマ: {conclusion:{status,headline},overall_rating,achievements[],problems[],delays[],approvals[],ceo_items[],manager_items[],tomorrow_priorities[],staff_summaries[{name,dept,text}],ai_analysis,urgent}';
const userText = '以下の日報データを分析し、JSONのみ出力してください。\n```json\n' + JSON.stringify(input, null, 2) + '\n```';
return [{ json: { dateISO, system, userText } }];

// Claudeの応答からJSONを取り出し、Kintone保存レコード & LINE messages を作る
const dateISO = $('Claude入力を作成').first().json.dateISO;
const content = ($json.content || []).filter(c => c.type === 'text').map(c => c.text).join('\n');
function parseJson(t){ let s=t.trim(); const f=s.match(/```(?:json)?\s*([\s\S]*?)```/i); if(f) s=f[1].trim(); const a=s.indexOf('{'),b=s.lastIndexOf('}'); if(a>-1&&b>-1) s=s.slice(a,b+1); return JSON.parse(s); }
let a; try { a = parseJson(content); } catch (e) { throw new Error('Claude応答のJSONパース失敗: ' + e.message + ' / raw=' + content.slice(0,300)); }
const DASH='情報不足';
const bul = (x)=> (Array.isArray(x)&&x.length)? x.map(y=>'・'+y).join('\n'):DASH;
const ln = (x)=> (x&&String(x).trim())?String(x).trim():DASH;
const join = (x)=> (Array.isArray(x)&&x.length)? x.join('\n'):DASH;
// LINE本文（簡潔版）
const c=a.conclusion||{}; const action=[...(a.problems||[]),...(a.delays||[])];
const lineText = `📊 Libetee 日報（${dateISO}）\n\n【結論】${c.status||'🟡'} ${ln(c.headline)}\n\n【成果】\n${bul(a.achievements)}\n\n【要対応】\n${bul(action)}\n\n【承認】\n${bul(a.approvals)}\n\n【明日の最優先】\n${bul(a.tomorrow_priorities)}\n\n詳細はKintoneをご確認ください。`;
// LINE分割（4800字/5吹き出し）
const MAX=4800; let rem=lineText; const bubbles=[];
while(rem.length>0){ if(rem.length<=MAX){bubbles.push(rem);break;} let cut=rem.lastIndexOf('\n',MAX); if(cut<MAX*0.5)cut=MAX; bubbles.push(rem.slice(0,cut)); rem=rem.slice(cut).replace(/^\n/,''); }
const messages = bubbles.slice(0,5).map(t=>({type:'text',text:t}));
// Kintone保存レコード
const record = {
  target_date:{value:dateISO}, overall_rating:{value:ln(a.overall_rating||c.status)}, conclusion:{value:ln(c.headline)},
  achievements:{value:join(a.achievements)}, problems:{value:join(a.problems)}, delays:{value:join(a.delays)},
  approvals:{value:join(a.approvals)}, ceo_items:{value:join(a.ceo_items)}, manager_items:{value:join(a.manager_items)},
  tomorrow_priorities:{value:join(a.tomorrow_priorities)},
  staff_summaries:{value:(a.staff_summaries||[]).map(s=>`${s.name}(${s.dept||'-'}): ${s.text}`).join('\n')||DASH},
  ai_analysis:{value:ln(a.ai_analysis)}, line_body:{value:lineText}, gen_status:{value:'生成成功'}, error_log:{value:''}
};
return [{ json: { dateISO, record, messages, urgent: !!a.urgent } }];

// 0件時: 未提出をLINE通知するための messages を作る
const dateISO = $('対象日と取得URLを作成').first().json.dateISO;
const text = `📊 Libetee 日報（${dateISO}）\n\n本日の日報提出はありませんでした。\n提出状況をご確認ください。`;
return [{ json: { messages: [{ type:'text', text }] } }];

// 取得したレコードから『日付・氏名・本文』を取り出し、対象日で絞り込む。
// lib/extractReports.js と同じ判定ロジック（フィールドコードに依存しない）。
const dateISO = $('対象日と取得URLを作成').first().json.dateISO;
const records = $json.records || [];
const TEXT_MIN = 25, NAME_MAX = 20;
const isDate = (v) => typeof v === 'string' && /^\d{4}-\d{2}-\d{2}/.test(v.trim());
const toISO  = (v) => (String(v).trim().match(/^(\d{4}-\d{2}-\d{2})/) || [])[1] || null;
const isBody = (v) => typeof v === 'string' && (v.includes('\n') || v.trim().length >= TEXT_MIN);
const isName = (v) => typeof v === 'string' && v.trim().length > 0 && v.trim().length <= NAME_MAX && !v.includes('\n') && !isDate(v);
function plain(f){ if(!f||typeof f!=='object') return null; const v=f.value;
  if(v===undefined||v===null||v==='') return null;
  if(Array.isArray(v)){ const n=v.map(x=>(x&&typeof x==='object')?(x.name||x.code||''):String(x)).filter(Boolean); return n.length?n.join(', '):null; }
  if(typeof v==='object') return null; return String(v); }
function fromRow(row, team){ const out=[]; let date=null, name=null;
  for(const [code,f] of Object.entries(row)){ if(code.startsWith('$')) continue;
    const v=plain(f); if(v===null) continue;
    if(isDate(v)){ date=toISO(v); continue; }
    if(isBody(v)){ out.push({date, reporter:name, team, text:v.trim()}); name=null; continue; }
    if(isName(v)) name=v.trim(); }
  return out; }
function isSub(f){ return f && Array.isArray(f.value) && f.value[0] && f.value[0].value && typeof f.value[0].value==='object'; }
const all=[];
for(const rec of records){ if(!rec||typeof rec!=='object') continue;
  let team=null;
  for(const [code,f] of Object.entries(rec)){ if(!code.startsWith('$') && /team|チーム/i.test(code)){ const v=plain(f); if(v){ team=v; break; } } }
  const top={};
  for(const [code,f] of Object.entries(rec)){ if(code.startsWith('$')) continue;
    if(isSub(f)){ for(const row of f.value) all.push(...fromRow(row.value, team)); } else { top[code]=f; } }
  all.push(...fromRow(top, team)); }
const reports = all.filter(r=>r.text).filter(r=>r.date===dateISO);
return [{ json: { dateISO, reports, count: reports.length } }];
